local Yielders = CS.Engine.Lib.Yielders
local BambooQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.BambooQuestComponent)
local BambooUtils = import('Game.UI.FightReady.UIBamboo.BambooUtils')
