---@field CommonUITitleNode             	UnityEngine.RectTransform               
---@field Root                          	UnityEngine.RectTransform               
local UIBambooChallengeDialog = Class("UIBambooChallengeDialog")

function UIBambooChallengeDialog:__init() 
    self._activityUuid = 0 
    self._activityId = 0           --当前活动id
    self._allChapter = {}          --所有的章节
end

function UIBambooChallengeDialog:__delete()
    self._activityUuid = nil 
    self._activityId = nil          
    self._allChapter = nil          
end

function UIBambooChallengeDialog:Awake()
    GameUtils.RefreshTopGoods(Constants.UITypeIds.UIBambooChallengeDialog)
    local argument = self.controller.Argument.parameters
    if not argument then
        return
    end
    self._activityUuid = checkNumber(argument.activityUuid)  
    if self._activityUuid == 0 then
        return
    end
    self._activityId = BambooUtils.GetActivityId(self._activityUuid)    --活动id
    if self._activityId == 0 then
        return
    end

    self._allChapter = BambooUtils.GetChallengeChapters(self._activityId)
    if not self._allChapter then
        return
    end
end

function UIBambooChallengeDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:FillSelf()
    end))
    return coWait
end

function UIBambooChallengeDialog:FillSelf()
    SetButtonAction(self.ButtonClose, Bind(self, self.OnButtonClose))
    local vo = BambooUtils.GetBambooActivityVo(self._activityId)
    if vo then
        CfUtils.FillText(self.TxtContent, string.gsub(vo.regionDesc, "\\n", "\n"))
    end 
    self:FillChapters()
end

--绘制章节
function UIBambooChallengeDialog:FillChapters()
    for i = 1, 6 do
        local go = self["BtnChapter"..(i)]
        CfUtils.SetActive(go, false)
    end

    for k, v in pairs(self._allChapter) do
        local go = self["BtnChapter"..checkString(v)]
        if go then
            CfUtils.SetActive(go, true)
            local scr = CfUtils.GetLuaScr(go, UIBambooChallengeNode)
            if scr then
                local vo = BambooUtils.GetQuestBambooChallengeChapterVo(v)
                scr:Refresh(vo, self._activityUuid)
            end
        end
    end
end

--退出按钮
function UIBambooChallengeDialog:OnButtonClose()
    UIModule.BackDialog()
end

